query:
{
  "settings": *[_id == "siteSettings"][0],
  "order": *[_id == "projectOrder"][0].projects[]._ref,
  "projects": *[_type == "project" && !(_id in path("drafts.**"))]{
    _id, title, "slug": slug.current, year, client, agency, type, role, description, team, recognition,
    content[]{ _type, caption, heading, body, url }
  }
}
